void Solver::rephase() {
    rephases = 0;
    // More aggressive threshold reduction to trigger local_best updates more frequently
    threshold *= 0.85;
    // Adaptive rephase_limit increase: use a larger step to allow more conflicts between rephases
    rephase_limit += 4096;
    // Additionally, inject some randomness into the saved phases to escape local optima
    int phase_rand = rand() % 100;
    if ((phase_rand -= 40) < 0) {
        // Use local_best phase (positive)
        for (int i = 1; i <= vars; i++) saved[i] = local_best[i];
    } else if ((phase_rand -= 15) < 0) {
        // Use inverted local_best phase
        for (int i = 1; i <= vars; i++) saved[i] = -local_best[i];
    } else if ((phase_rand -= 20) < 0) {
        // Random phase assignment
        for (int i = 1; i <= vars; i++) saved[i] = rand() % 2 ? 1 : -1;
    } else if ((phase_rand -= 10) < 0) {
        // All positive phase
        for (int i = 1; i <= vars; i++) saved[i] = 1;
    } else if ((phase_rand -= 10) < 0) {
        // All negative phase
        for (int i = 1; i <= vars; i++) saved[i] = -1;
    }
    // else: keep current saved phases (phase saving from backtrack)
}
